/* Cyberpunk Theme — Tailwind v3 (hsl) */
/* Channel triplets — consume via hsl(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Cyberpunk Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 300 0% 97.37%;
    --foreground: 241.26 48.11% 7.87%;
    --card: 300 50% 100%;
    --card-foreground: 241.26 48.11% 7.87%;
    --popover: 300 50% 100%;
    --popover-foreground: 241.26 48.11% 7.87%;
    --primary: 312.95 99.97% 49.75%;
    --primary-foreground: 300 50% 100%;
    --secondary: 240 99.88% 97.09%;
    --secondary-foreground: 241.26 48.11% 7.87%;
    --muted: 240 99.88% 97.09%;
    --muted-foreground: 241.26 48.11% 7.87%;
    --accent: 166.49 99.27% 56.2%;
    --accent-foreground: 241.26 48.11% 7.87%;
    --destructive: 13.38 97.43% 51.15%;
    --destructive-foreground: 300 50% 100%;
    --border: 197.99 21.4% 89.31%;
    --input: 197.99 21.4% 89.31%;
    --ring: 312.95 99.97% 49.75%;
    --chart-1: 312.95 99.97% 49.75%;
    --chart-2: 272.59 98.63% 52.32%;
    --chart-3: 186.13 99.7% 49.75%;
    --chart-4: 166.49 99.27% 56.2%;
    --chart-5: 53.33 100% 58.05%;
    --radius: 0.5rem;
    --sidebar: 240 99.88% 97.09%;
    --sidebar-foreground: 241.26 48.11% 7.87%;
    --sidebar-primary: 312.95 99.97% 49.75%;
    --sidebar-primary-foreground: 300 50% 100%;
    --sidebar-accent: 166.49 99.27% 56.2%;
    --sidebar-accent-foreground: 241.26 48.11% 7.87%;
    --sidebar-border: 197.99 21.4% 89.31%;
    --sidebar-ring: 312.95 99.97% 49.75%;
    --font-sans: Outfit, sans-serif;
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono: Fira Code, monospace;
    --shadow-color: 0 0% 0%;
    --shadow-opacity: 0.1;
    --shadow-blur: 8px;
    --shadow-spread: -2px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 4px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 4px 8px -2px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0px 4px 8px -2px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
    --shadow:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 2px 4px -3px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 4px 6px -3px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 8px 10px -3px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0px 4px 8px -2px hsl(0 0% 0% / 0.25);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 241.26 48.11% 7.87%;
    --foreground: 217.5 35.81% 94.12%;
    --card: 239.98 35.67% 17.74%;
    --card-foreground: 217.5 35.81% 94.12%;
    --popover: 239.98 35.67% 17.74%;
    --popover-foreground: 217.5 35.81% 94.12%;
    --primary: 312.95 99.97% 49.75%;
    --primary-foreground: 300 50% 100%;
    --secondary: 239.98 35.67% 17.74%;
    --secondary-foreground: 217.5 35.81% 94.12%;
    --muted: 239.98 35.67% 17.74%;
    --muted-foreground: 232.11 17.33% 57.11%;
    --accent: 166.49 99.27% 56.2%;
    --accent-foreground: 241.26 48.11% 7.87%;
    --destructive: 13.38 97.43% 51.15%;
    --destructive-foreground: 300 50% 100%;
    --border: 239.6 33.21% 27.41%;
    --input: 239.6 33.21% 27.41%;
    --ring: 312.95 99.97% 49.75%;
    --chart-1: 312.95 99.97% 49.75%;
    --chart-2: 272.59 98.63% 52.32%;
    --chart-3: 186.13 99.7% 49.75%;
    --chart-4: 166.49 99.27% 56.2%;
    --chart-5: 53.33 100% 58.05%;
    --radius: 0.5rem;
    --sidebar: 241.26 48.11% 7.87%;
    --sidebar-foreground: 217.5 35.81% 94.12%;
    --sidebar-primary: 312.95 99.97% 49.75%;
    --sidebar-primary-foreground: 300 50% 100%;
    --sidebar-accent: 166.49 99.27% 56.2%;
    --sidebar-accent-foreground: 241.26 48.11% 7.87%;
    --sidebar-border: 239.6 33.21% 27.41%;
    --sidebar-ring: 312.95 99.97% 49.75%;
    --font-sans: Outfit, sans-serif;
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono: Fira Code, monospace;
    --shadow-color: 0 0% 0%;
    --shadow-opacity: 0.1;
    --shadow-blur: 8px;
    --shadow-spread: -2px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 4px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 4px 8px -2px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0px 4px 8px -2px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
    --shadow:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 2px 4px -3px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 4px 6px -3px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 8px 10px -3px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0px 4px 8px -2px hsl(0 0% 0% / 0.25);
  }

}
